"""Planning project load: team initials without the allocation history."""

from datetime import date

import pytest
from alloq_commons.entities import (
    CapacityAllocationEntity,
    EmployeeEntity,
    ProjectEntity,
    RoleEntity,
    SeniorityLevel,
)
from alloq_project.services.planning_projects import (
    load_planning_projects,
    team_initials_by_project,
)
from sqlalchemy.ext.asyncio import AsyncSession

# Wednesday start: the project's first week begins Monday 2026-03-02.
START = date(2026, 3, 4)


class TestTeamInitialsByProject:
    def test_week_of_start_counts(self) -> None:
        rows = [(1, "Anna", "Berg", date(2026, 3, 2))]

        assert team_initials_by_project({1: START}, rows) == {1: ["AB"]}

    def test_staffed_only_before_start_is_dropped(self) -> None:
        rows = [(1, "Anna", "Berg", date(2026, 2, 23))]

        assert team_initials_by_project({1: START}, rows) == {}

    def test_unknown_project_is_dropped(self) -> None:
        rows = [(2, "Anna", "Berg", date(2026, 3, 9))]

        assert team_initials_by_project({1: START}, rows) == {}

    def test_keeps_row_order(self) -> None:
        rows = [
            (1, "Anna", "Arndt", date(2026, 3, 9)),
            (1, "Zoe", "Zander", date(2026, 3, 9)),
        ]

        assert team_initials_by_project({1: START}, rows) == {1: ["AA", "ZZ"]}


class TestLoadPlanningProjects:
    @pytest.mark.asyncio
    async def test_team_initials_from_staffed_weeks(
        self, async_session: AsyncSession
    ) -> None:
        project = ProjectEntity(
            code="PLAN",
            name_de="Planung",
            start_date=START,
            end_date=date(2026, 3, 27),
            budget=1000,
            color="#000000",
        )
        employee = EmployeeEntity(
            first_name="Anna",
            last_name="Berg",
            seniority=SeniorityLevel.SENIOR.value,
            hours_per_week=40,
        )
        role = RoleEntity(name="Dev")
        async_session.add_all([project, employee, role])
        await async_session.flush()
        async_session.add(
            CapacityAllocationEntity(
                project_id=project.id,
                employee_id=employee.id,
                role_id=role.id,
                week_start=date(2026, 3, 9),
                person_days=2.0,
            )
        )
        await async_session.flush()
        async_session.expunge_all()

        projects = await load_planning_projects(async_session)

        assert [(p.code, p.team_initials) for p in projects] == [("PLAN", ["AB"])]

